"""Creative brief for each of the 35 catalogue-scoped MISSING Dan assets (spec §7).

Each scene is deliberately different (no repeated 'golden autumn Gothic steps + books + mug'
template). Settings name real Yale places only as visual inspiration for the image model;
the studio makes no claim that a generated building is an accurate depiction.
permitted_text lists the ONLY words allowed to appear in the image. Never 'Dan <Institution>'.
"""

def _a(display_name, setting, outfit, pose, humor, permitted_text=("YALE",), shield=None):
    return {"display_name": display_name, "setting": setting, "outfit": outfit, "pose": pose,
            "humor": humor, "permitted_text": list(permitted_text), "shield": shield}


